  var diseaseKeywordsMap = {
    "tic-disorder": ["틱", "뚜렛"],
    "panic-disorder": ["공황", "발작"],
    "dizziness": ["어지럼", "이석", "메니에르", "전정"],
    "dysautonomia": ["자율신경", "교감신경", "부교감신경", "기립"],
    "insomnia": ["불면", "수면"],
    "adhd": ["adhd", "주의력", "산만"],
    "anxiety-disorder": ["불안", "범불안"],
    "ocd": ["강박"],
    "social-phobia": ["사회", "대인", "시선", "발표", "적면"],
    "hyperhidrosis": ["다한", "땀"],
    "climacteric": ["갱년기", "폐경", "상열감", "안면홍조", "호르몬"]
  };

  var diseaseUrlMap = {
    "틱장애": "/tic-disorder/",
    "공황장애": "/panic-disorder/",
    "불면증": "/insomnia/",
    "자율신경실조증": "/dysautonomia/",
    "어지럼증": "/dizziness/",
    "ADHD": "/adhd/",
    "강박증": "/ocd/",
    "대인기피증": "/social-phobia/",
    "불안장애": "/anxiety-disorder/",
    "갱년기": "/climacteric/",
    "갱년기증후군": "/climacteric/",
    "다한증": "/hyperhidrosis/"
  };

  function getCurrentDiseaseSlug() {
    var wrapper = document.querySelector('.healim-bottom-section-wrapper');
    if (wrapper && wrapper.getAttribute('data-disease-slug')) {
      var s = wrapper.getAttribute('data-disease-slug').trim();
      if (s) return s;
    }
    var cleanPath = window.location.pathname.replace(/^\/+|\/+$/g, '');
    if (diseaseKeywordsMap[cleanPath]) {
      return cleanPath;
    }
    return '';
  }

  function matchesDisease(item, slug) {
    if (!slug || !diseaseKeywordsMap[slug]) return false;
    var keywords = diseaseKeywordsMap[slug];
    var text = (
      (item.disease || '') + ' ' +
      (item.category || '') + ' ' +
      (item.tag || '') + ' ' +
      (item.title || '') + ' ' +
      (item.q || '')
    ).toLowerCase();

    return keywords.some(function(kw) {
      return text.indexOf(kw.toLowerCase()) !== -1;
    });
  }

  function parseDateStrToTime(dStr) {
    if (!dStr) return 0;
    var clean = String(dStr).replace(/\./g, '-').trim();
    var t = Date.parse(clean);
    return isNaN(t) ? 0 : t;
  }

  function escapeHtml(str) {
    if (!str) return '';
    return String(str)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#39;');
  }

  function getColumnImage(col) {
    if (col && col.img && col.img.length > 5) return col.img;
    var cat = ((col ? (col.category || '') + ' ' + (col.title || '') : '')).toLowerCase();
    if (cat.indexOf('틱') !== -1) return '/images/columns/column_23_bruxism_tmj.svg';
    if (cat.indexOf('공황') !== -1) return '/images/columns/column_1_palpitation.svg';
    if (cat.indexOf('자율신경') !== -1) return '/images/columns/column_14_vagus_stimulation.svg';
    if (cat.indexOf('불면') !== -1) return '/images/columns/column_15_neurotransmitter.svg';
    if (cat.indexOf('어지럼') !== -1) return '/images/columns/column_4_pots_dizziness.svg';
    if (cat.indexOf('adhd') !== -1) return '/images/columns/column_5_neuroplasticity.svg';
    if (cat.indexOf('강박') !== -1) return '/images/columns/column_18_gut_brain_axis.svg';
    if (cat.indexOf('불안') !== -1) return '/images/columns/column_29_panic_boundary.svg';
    if (cat.indexOf('다한') !== -1 || cat.indexOf('땀') !== -1) return '/images/columns/column_9_sweat_dysregulation.svg';
    if (cat.indexOf('사회') !== -1 || cat.indexOf('대인') !== -1) return '/images/columns/column_13_somatization.svg';
    if (cat.indexOf('갱년기') !== -1 || cat.indexOf('폐경') !== -1) return '/images/columns/column_16_hormone.svg';
    return '/images/columns/column_1_palpitation.svg';
  }

  function getRealtimeBoardData(boardType) {
    try {
      if (boardType === 'faq') {
        var local = localStorage.getItem('healim_board_faqs') || localStorage.getItem('healim_board_faqs_permanent_backup');
        var delList = JSON.parse(localStorage.getItem('healim_deleted_faq_ids') || '[]');
        var list = local ? JSON.parse(local) : [];
        if (!Array.isArray(list)) list = [];
        list = list.filter(function(it) {
          return it && delList.indexOf(String(it.id)) === -1 && delList.indexOf(String(it.q)) === -1;
        });
        defaultBottomFaqs.forEach(function(item) {
          var isDel = delList.indexOf(String(item.id)) !== -1 || delList.indexOf(String(item.q)) !== -1;
          if (!isDel) {
            var exists = list.some(function(p) { return p.id === item.id || p.q === item.q; });
            if (!exists) list.push(item);
          }
        });
        // diseaseFaqsMap is handled per-page when currentSlug exists
        list.sort(function(a, b) {
          var tA = parseDateStrToTime(a.date);
          var tB = parseDateStrToTime(b.date);
          if (tB !== tA) return tB - tA;
          return String(b.id || '').localeCompare(String(a.id || ''));
        });
        return list;
      } else if (boardType === 'reviews') {
        var local = localStorage.getItem('healim_board_reviews');
        var list = local ? JSON.parse(local) : [];
        if (!Array.isArray(list)) list = [];
        defaultBottomReviews.forEach(function(item) {
          var exists = list.some(function(p) { return p.id === item.id || (p.title && p.title === item.title); });
          if (!exists) list.push(item);
        });
        for (var dKey in diseaseReviewsMap) {
          diseaseReviewsMap[dKey].forEach(function(item) {
            var exists = list.some(function(p) { return p.id === item.id || (p.title && p.title === item.title); });
            if (!exists) list.push(item);
          });
        }
        list.sort(function(a, b) {
          var tA = parseDateStrToTime(a.date);
          var tB = parseDateStrToTime(b.date);
          if (tB !== tA) return tB - tA;
          return (parseInt(b.id, 10) || 0) - (parseInt(a.id, 10) || 0);
        });
        return list;
      } else if (boardType === 'columns') {
        try {
          if (typeof window.syncDeterministicAutoPublish === 'function') {
            window.syncDeterministicAutoPublish();
          }
        } catch(e) {}
        var local = localStorage.getItem('healim_board_columns') || localStorage.getItem('healim_board_columns_permanent_backup');
        var delList = JSON.parse(localStorage.getItem('healim_deleted_column_ids') || '[]');
        var list = local ? JSON.parse(local) : [];
        if (!Array.isArray(list)) list = [];
        var normTitleFn = function(t) { return String(t || '').replace(/\s+/g, '').trim(); };
        var canonicalBottomIds = {};
        var canonicalBottomTitles = {};
        var editedBottomMap = {};
        defaultBottomColumns.forEach(function(item) {
          if (!item || !item.id) return;
          canonicalBottomIds[String(item.id)] = true;
          if (item.title) canonicalBottomTitles[normTitleFn(item.title)] = true;
        });
        list.forEach(function(it) {
          if (it && it.id && it.editedByAdmin) {
            editedBottomMap[String(it.id)] = it;
          }
        });
        list = list.filter(function(it) {
          if (!it) return false;
          var sid = String(it.id || '');
          var cCat = it.category || '';
          var cTitle = it.title || '';
          var cContent = it.content || '';
          if (cCat.includes('대인') || cCat.includes('사회')) {
            if (cTitle.includes('틱') || cTitle.includes('기저핵') || cTitle.includes('눈 깜빡임')) return false;
            if (cContent.includes('일시적인 틱은') || cContent.includes('도파민 수용체 감수성') || cContent.includes('뚜렛')) return false;
          }
          if (cCat.includes('틱') && (cTitle.includes('대인기피') || cTitle.includes('사회공포'))) return false;
          if (it.id === 'corrupted-mobile-49' || it.id === 'corrupted-pc-48') return false;
          if (canonicalBottomIds[sid] || (cTitle && canonicalBottomTitles[normTitleFn(cTitle)])) return false;
          if (sid.indexOf('col-auto-') === 0 && sid.indexOf('col-auto-sched-') !== 0 && sid.indexOf('col-auto-manual-') !== 0) return false;
          return delList.indexOf(String(it.id)) === -1 && delList.indexOf(String(it.title)) === -1;
        });
        defaultBottomColumns.forEach(function(item) {
          var isDel = delList.indexOf(String(item.id)) !== -1 || delList.indexOf(String(item.title)) !== -1;
          if (!isDel) {
            var effItem = editedBottomMap[String(item.id)] ? Object.assign({}, item, editedBottomMap[String(item.id)]) : item;
            var normItemTitle = normTitleFn(effItem.title);
            var exists = list.some(function(p) { return p.id === effItem.id || normTitleFn(p.title) === normItemTitle; });
            if (!exists) list.push(effItem);
          }
        });
        // diseaseColumnsMap is handled per-page when currentSlug exists
        list.sort(function(a, b) {
          var tA = parseDateStrToTime(a.date);
          var tB = parseDateStrToTime(b.date);
          if (tB !== tA) return tB - tA;
          return String(b.id || '').localeCompare(String(a.id || ''));
        });
        return list;
      } else if (boardType === 'youtube') {
        var local = localStorage.getItem('healim_board_youtube');
        var list = local ? JSON.parse(local) : [];
        if (!Array.isArray(list)) list = [];
        defaultBottomYoutube.forEach(function(item) {
          var exists = list.some(function(p) { return p.id === item.id || p.vid === item.vid; });
          if (!exists) list.push(item);
        });
        return list;
      }
    } catch(e) {
      console.error('[Healim Realtime] Board data error:', e);
    }
    return [];
  }

  function renderCommonBottomColumnsRealtime() {
    var container = document.getElementById('commonBottomColumnsList');
    if (!container) return;

    var currentSlug = getCurrentDiseaseSlug();
    // 질환 페이지는 질환별 칼럼, 메인(/) 및 about(/about) 페이지는 최신 발행 칼럼 실시간 반영
    var allCols = getRealtimeBoardData('columns');
    var list = [];

    if (currentSlug) {
      var matched = allCols.filter(function(it) { return matchesDisease(it, currentSlug); });
      var defCols = (typeof diseaseColumnsMap !== 'undefined' && diseaseColumnsMap[currentSlug]) ? diseaseColumnsMap[currentSlug] : [];

      matched.forEach(function(it) { list.push(it); });
      defCols.forEach(function(it) {
        var exists = list.some(function(p) { return p.id === it.id || p.title === it.title; });
        if (!exists) list.push(it);
      });
    } else {
      list = allCols;
    }

    if (!list || list.length === 0) return;

    // 최신순 정렬: 최신 날짜가 0번 인덱스(제일 왼쪽)에 위치
    list.sort(function(a, b) {
      return parseDateStrToTime(b.date) - parseDateStrToTime(a.date);
    });

    var topItems = list.slice(0, 3);
    var html = '';

    topItems.forEach(function(item) {
      var idStr = String(item.id || '');
      var imgSrc = getColumnImage(item);
      var category = escapeHtml(item.category || '치료칼럼');
      var title = escapeHtml(item.title || '');
      var desc = escapeHtml(item.summary || item.desc || (item.content ? item.content.slice(0, 110) + '...' : ''));
      var author = escapeHtml(item.author || '해아림한의원');
      var date = escapeHtml(item.date || '2026.10.12');

      html += '<li class="bottom-item-card bottom-column-card" onclick="openCommonBottomDetail(&quot;columns&quot;, &quot;' + idStr + '&quot;)">';
      html += '  <div class="bottom-column-body">';
      html += '    <div class="bottom-column-top-meta">';
      html += '      <span class="bottom-card-category">' + category + '</span>';
      html += '      <span class="bottom-column-date">' + date + '</span>';
      html += '    </div>';
      html += '    <h3 class="bottom-card-title">' + title + '</h3>';
      html += '    <p class="bottom-card-desc">' + desc + '</p>';
      html += '    <div class="bottom-card-footer">';
      html += '      <span>' + author + '</span>';
      html += '      <span class="bottom-column-read-btn">칼럼 읽기 &gt;</span>';
      html += '    </div>';
      html += '  </div>';
      html += '  <div class="bottom-card-media bottom-column-media">';
      html += '    <img src="' + imgSrc + '" alt="' + title + '" onerror="this.onerror=null; this.src=&quot;/images/books/book_tic.png&quot;;">';
      html += '  </div>';
      html += '</li>';
    });

    container.innerHTML = html;
  }

